create or replace view v_manufacturing_order_current_operation with(security_invoker=true)as select e.organization_id,e.production_order_id manufacturing_order_id,po.mo_number,coalesce(e.source_order_no,e.order_no)source_order_no,po.routing_code_snapshot,po.routing_revision_snapshot,e.production_status,e.planned_quantity,e.actual_quantity,greatest(coalesce(e.planned_quantity,0)-coalesce(e.actual_quantity,0),0)remaining_quantity,e.planned_date,e.planner_priority,e.current_operation_id,e.current_operation_code,e.current_operation_name,e.next_operation_id,e.next_operation_code,e.next_operation_name,e.last_completed_operation_id,e.last_completed_operation_code from v_production_order_execution e join production_orders po on po.id=e.production_order_id where po.source_routing_id is not null;
create or replace view v_manufacturing_order_progress with(security_invoker=true)as select m.*,count(op.id)operation_count,count(op.id)filter(where op.status='COMPLETED')completed_operation_count,round(count(op.id)filter(where op.status='COMPLETED')::numeric/nullif(count(op.id),0)*100,1)routing_progress_percent from v_manufacturing_order_current_operation m left join production_order_operations op on op.production_order_id=m.manufacturing_order_id group by m.organization_id,m.manufacturing_order_id,m.mo_number,m.source_order_no,m.routing_code_snapshot,m.routing_revision_snapshot,m.production_status,m.planned_quantity,m.actual_quantity,m.remaining_quantity,m.planned_date,m.planner_priority,m.current_operation_id,m.current_operation_code,m.current_operation_name,m.next_operation_id,m.next_operation_code,m.next_operation_name,m.last_completed_operation_id,m.last_completed_operation_code;
create or replace view v_manufacturing_order_routing_status with(security_invoker=true)as select p.*,coalesce(s.open_exception_count,0)open_exception_count,s.last_source_observed_at,case when coalesce(s.open_exception_count,0)>0 then'DEVIATION'when s.evidence_count>0 then'VALIDATED'else'AWAITING_EVIDENCE'end validation_status from v_manufacturing_order_progress p left join v_production_order_routing_status s on s.production_order_id=p.manufacturing_order_id;
create or replace view v_flow_operation_detail with(security_invoker=true)as select m.*,o.customer_name,o.ship_to_name,o.date_due,coalesce(o.date_due::date,m.planned_date)due_date,greatest(0,current_date-coalesce(o.date_due::date,m.planned_date,current_date))age_days,o.source_priority,coalesce((select jsonb_agg(jsonb_build_object('sku',p.sku,'description',p.description,'planned_quantity',l.planned_quantity,'actual_quantity',l.actual_quantity)order by l.sequence)from manufacturing_order_lines l left join products p on p.id=l.product_id where l.manufacturing_order_id=m.manufacturing_order_id),'[]'::jsonb)product_mix from v_manufacturing_order_routing_status m left join v_current_orders o on o.organization_id=m.organization_id and o.order_no=m.source_order_no;
create or replace view v_flow_operation_summary with(security_invoker=true)as select organization_id,routing_code_snapshot,current_operation_code,sum(remaining_quantity)units,count(*)mo_count,count(distinct source_order_no)so_count,round(avg(age_days),1)average_age,max(age_days)oldest_age,count(*)filter(where coalesce(planner_priority,source_priority,999)<=10 or age_days>4)critical_priority_count from v_flow_operation_detail where production_status not in('COMPLETED','CANCELLED')and current_operation_code is not null group by organization_id,routing_code_snapshot,current_operation_code;
grant select on v_manufacturing_order_current_operation,v_manufacturing_order_progress,v_manufacturing_order_routing_status,v_flow_operation_detail,v_flow_operation_summary to authenticated,service_role;
drop view if exists v_production_flow_routing_reconciliation;
create view v_production_flow_routing_reconciliation with(security_invoker=true)as with stages(stage_code,routing_prefix,operation_code)as(values('DTG_PICKING','DTG%','PICKING'),('DTG_PRINTING','DTG%','DTG_PRINT'),('DTG_PUTWALL','DTG%','PUTWALL'),('DTG_DISPATCH','DTG%','DISPATCH'),('UP_PICKING','UNDERPRINT%','PICKING'),('UP_PRINTING','UNDERPRINT%','UNDERPRINT'),('UP_DISPATCH','UNDERPRINT%','DISPATCH')),orgs as(select id organization_id from organizations),r as(select o.organization_id,s.stage_code,coalesce(sum(f.units),0)units,coalesce(sum(f.mo_count),0)orders from orgs o cross join stages s left join v_flow_operation_summary f on f.organization_id=o.organization_id and f.routing_code_snapshot ilike s.routing_prefix and f.current_operation_code=s.operation_code group by o.organization_id,s.stage_code),l as(select organization_id,stage_code,units,orders from v_production_flow_legacy_snapshot)select r.organization_id,r.stage_code,coalesce(l.units,0)legacy_units,r.units routing_units,r.units-coalesce(l.units,0)unit_difference,coalesce(l.orders,0)legacy_orders,r.orders routing_orders,r.orders-coalesce(l.orders,0)order_difference,case when r.units=coalesce(l.units,0)and r.orders=coalesce(l.orders,0)then'MATCH'when r.orders=0 and coalesce(l.orders,0)>0 then'MISSING_MO'when r.units>coalesce(l.units,0)then'DOUBLE_COUNT'else'UNKNOWN'end difference_category from r left join l using(organization_id,stage_code);
